// TypeScript mirror of server/pulselens/models.py and config.yaml (both generated by `make types`),
// plus unions of the WebSocket messages, which the generator does not emit.
import type {
  DoneMessage, EventMessage, Heartbeat, PromptMessage, PulseAck, PulseMessage, StageDone, StageMessage,
} from "./models.gen";

export * from "./config.gen";
export * from "./models.gen";

/** Server to capture device on /ws/session/{id}. `event` reaches the lab role only, never a customer. */
export type CaptureServerMessage = StageMessage | PromptMessage | PulseMessage | DoneMessage | EventMessage;
/** Capture device to server. */
export type CaptureClientMessage = PulseAck | StageDone | Heartbeat;
